CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT uuidv7(), email text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses (id uuid PRIMARY KEY DEFAULT uuidv7(), name text NOT NULL, timezone text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), business_id uuid NOT NULL REFERENCES businesses(id), role text NOT NULL CHECK (role IN ('customer','mechanic','admin')), PRIMARY KEY (user_id,business_id));
CREATE TABLE IF NOT EXISTS vehicles (id uuid PRIMARY KEY DEFAULT uuidv7(), customer_id uuid NOT NULL REFERENCES users(id), vin text, year integer NOT NULL, make text NOT NULL, model text NOT NULL, mileage integer, mileage_recorded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_requests (id uuid PRIMARY KEY DEFAULT uuidv7(), customer_id uuid NOT NULL REFERENCES users(id), vehicle_id uuid NOT NULL REFERENCES vehicles(id), category text NOT NULL, symptoms text, delivery_mode text NOT NULL CHECK (delivery_mode IN ('mobile','shop')), status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quotes (id uuid PRIMARY KEY DEFAULT uuidv7(), request_id uuid NOT NULL REFERENCES service_requests(id), customer_id uuid NOT NULL REFERENCES users(id), version integer NOT NULL DEFAULT 1, status text NOT NULL CHECK (status IN ('draft','issued','accepted','superseded','expired','declined')), currency char(3) NOT NULL, total_minor bigint NOT NULL CHECK (total_minor >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (id, version));
CREATE TABLE IF NOT EXISTS quote_lines (id uuid PRIMARY KEY DEFAULT uuidv7(), quote_id uuid NOT NULL REFERENCES quotes(id), description text NOT NULL, amount_minor bigint NOT NULL, quantity numeric(12,3) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS appointments (id uuid PRIMARY KEY DEFAULT uuidv7(), quote_id uuid REFERENCES quotes(id), customer_id uuid NOT NULL REFERENCES users(id), mechanic_id uuid REFERENCES users(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL, status text NOT NULL, version integer NOT NULL DEFAULT 1, CHECK (ends_at > starts_at));
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT uuidv7(), appointment_id uuid REFERENCES appointments(id), customer_id uuid NOT NULL REFERENCES users(id), mechanic_id uuid REFERENCES users(id), status text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals (id uuid PRIMARY KEY DEFAULT uuidv7(), quote_id uuid NOT NULL REFERENCES quotes(id), quote_version integer NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL, accepted_total_minor bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT uuidv7(), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id uuid NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_records (key text PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_vehicles_customer ON vehicles(customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_customer ON jobs(customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_mechanic ON jobs(mechanic_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_appointments_active ON appointments(mechanic_id, starts_at, ends_at) WHERE status IN ('held','confirmed','scheduled');
